// Parse the webhook payload (sent as text/plain to avoid CORS preflight)
const item = $input.first().json;
let payload = item.body;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
}
payload = payload || {};
const genreDefaults = { beauty: 100939, food: 100227, living: 562637 };
const category = ['beauty', 'food', 'living'].includes(payload.category) ? payload.category : 'beauty';
return [{
  json: {
    category,
    categoryLabel: payload.categoryLabel || category,
    priceRange: String(payload.priceRange || ''),
    channel: String(payload.channel || ''),
    genreId: Number(payload.genreId) || genreDefaults[category],
    referenceTrendSummary: payload.referenceTrendSummary || null,
    rakutenAppId: item.rakutenAppId || '',
    anthropicModel: item.anthropicModel || 'claude-sonnet-5'
  }
}];

// Build the grounded Claude request (same strengthened prompt as the dashboard)
const prep = $('Prepare').first().json;
const rk = $input.first().json;
const items = Array.isArray(rk.Items) ? rk.Items.map(x => x.Item || x) : [];

const context = {
  category: prep.categoryLabel,
  priceRange: prep.priceRange,
  channel: prep.channel,
  referenceTrendSummary: prep.referenceTrendSummary
};
let hasLive = false;
if (items.length) {
  hasLive = true;
  const prices = items.map(i => Number(i.itemPrice)).filter(Number.isFinite).sort((a, b) => a - b);
  const median = prices.length ? (prices.length % 2 ? prices[Math.floor(prices.length / 2)] : Math.round((prices[prices.length / 2 - 1] + prices[prices.length / 2]) / 2)) : null;
  context.liveMarketData = {
    source: 'Rakuten Ichiba Ranking API — real-time best sellers, fetched moments ago',
    fetchedAt: new Date().toISOString(),
    medianPriceYen: median,
    topItems: items.slice(0, 10).map(i => ({
      rank: i.rank,
      name: String(i.itemName || '').slice(0, 70),
      priceYen: Number(i.itemPrice) || null,
      reviewCount: Number(i.reviewCount) || 0,
      reviewAverage: Number(i.reviewAverage) || null
    }))
  };
}

const liveRules = hasLive ? `\n- liveMarketData contains REAL best-selling items fetched from Rakuten Ichiba minutes ago. Treat it as the primary evidence: analyze what the top items have in common (function, format, claims), find an unserved gap, and design the concept to win that gap rather than imitate the leaders.\n- Anchor pricing to liveMarketData: position the target retail price relative to medianPriceYen and the observed price range, and say so explicitly in the price section.\n- In marketEvidence, cite at least 2 concrete observations from liveMarketData and state the gap this concept exploits. Refer to items generically (by rank or characteristic), never by their brand names.` : `\n- Only reference trend data comes from referenceTrendSummary; treat it as directional, not real-time, and keep claims proportionate.`;

const system = `You are a senior product manager and market analyst who supports Korean companies in developing OEM products for the Japanese market. You have deep knowledge of Japanese consumer behavior, e-commerce merchandising, and Japanese regulations (薬機法 / Pharmaceutical and Medical Device Act, 食品表示法 / Food Labeling Act, 景品表示法 / Act against Unjustifiable Premiums, PSE for electricals).\nBased on the provided Japanese market data, propose exactly one highly original OEM product concept.\n\nGrounding rules (critical for accuracy):\n- Base every section on the data provided. Do NOT invent market facts that contradict it.${liveRules}\n- The concept must be feasible for a Korean OEM/ODM factory to produce and export to Japan.\n- Regulatory bullets must name the specific Japanese law/rule and the concrete action required — no generic advice.\n\nOutput constraints:\n- Keep the JSON field names exactly as specified below, and write ALL JSON field values in English (currency amounts may use the yen sign, e.g. ¥1,980).\n- The brand name and product name must be completely original coined words that never duplicate or resemble any real brand or product in Japan or Korea.\n- Your output must consist of the JSON only, with no other text and no code fences.\n- Every hex value in colors must use the \"#rrggbb\" format.\n\n{\n  \"brandName\": \"Original brand name in Latin letters\",\n  \"productName\": \"Product name (in English)\",\n  \"packageLabel\": \"Short package label in capital letters (max 12 characters)\",\n  \"packageSub\": \"Short package sub-copy in Latin letters (max 24 characters)\",\n  \"lead\": \"Product concept summary in English (about 160 characters)\",\n  \"marketEvidence\": [\"3 bullet points citing the specific market data observations that justify this concept\"],\n  \"target\": [\"3 bullet points\"],\n  \"spec\": [\"3 bullet points\"],\n  \"price\": [\"3 bullet points — the first must contain a target retail price such as ¥1,980\"],\n  \"regulatory\": [\"3 bullet points, each naming the specific law and required action\"],\n  \"images\": [\n    {\"name\": \"Concept A\", \"desc\": \"Design intent (about 80 characters)\", \"colors\": {\"bg1\":\"#hex\",\"bg2\":\"#hex\",\"body\":\"#hex\",\"cap\":\"#hex\",\"text\":\"#hex\",\"mist\":\"#hex\"}},\n    {\"name\": \"Concept B\", \"desc\": \"...\", \"colors\": {\"bg1\":\"#hex\",\"bg2\":\"#hex\",\"body\":\"#hex\",\"cap\":\"#hex\",\"text\":\"#hex\",\"mist\":\"#hex\"}},\n    {\"name\": \"Concept C\", \"desc\": \"...\", \"colors\": {\"bg1\":\"#hex\",\"bg2\":\"#hex\",\"body\":\"#hex\",\"cap\":\"#hex\",\"text\":\"#hex\",\"mist\":\"#hex\"}}\n  ]\n}`;

const user = `Based on the following conditions and Japanese EC market data, propose one OEM product concept in the JSON format specified. Write all field values in English.\n\n${JSON.stringify(context, null, 2)}`;

return [{
  json: {
    claudeBody: {
      model: prep.anthropicModel,
      max_tokens: 6000,
      system,
      messages: [{ role: 'user', content: user }]
    }
  }
}];

// Assemble the final response: plan + 3 data-URL images (missing ones stay null)
const plan = $('Parse Plan').first().json.plan;
const images = [null, null, null];
$input.all().forEach((item, i) => {
  const idx = $('Parse Plan').all()[i] ? $('Parse Plan').all()[i].json.idx : i;
  let url = null;
  // OpenRouter (chat/completions) format
  const orImages = item.json.choices?.[0]?.message?.images || [];
  const orHit = orImages.find(p => p.image_url && p.image_url.url);
  if (orHit) url = orHit.image_url.url;
  // Gemini native format (fallback)
  if (!url) {
    const parts = item.json.candidates?.[0]?.content?.parts || [];
    const imgPart = parts.find(p => p.inlineData && p.inlineData.data);
    if (imgPart) url = `data:${imgPart.inlineData.mimeType || 'image/png'};base64,${imgPart.inlineData.data}`;
  }
  if (url && /^data:image\//.test(url)) images[idx] = url;
});
return [{
  json: {
    plan,
    images,
    meta: {
      generatedAt: new Date().toISOString(),
      orchestrator: 'n8n',
      imageProvider: 'openrouter/google/gemini-2.5-flash-image',
      liveDataUsed: !!$('Build Claude Request').first().json.claudeBody.system.includes('liveMarketData contains REAL')
    }
  }
}];
